(()=>{const p=(location.pathname.replace(/\/+$/,'')||'/'),job='/internal/admin/jobs/create-job',room='/internal/admin/control-room';function hold(text,sub){if(document.querySelector('.mmd-admin-hold'))return;let d=document.createElement('div');d.className='mmd-admin-hold';d.innerHTML='<b>'+text+'</b><small>'+sub+'</small>';document.body.prepend(d)}function fix(){if(p==='/internal/admin/member-intelligence'){document.querySelectorAll('a[href*="/internal/admin/jobs/create-session"]').forEach(a=>{a.href=a.href.replace('/internal/admin/jobs/create-session',job);if(/Create Session/i.test(a.textContent))a.textContent=a.textContent.replace(/Create Session/ig,'Create Job')})}if(p==='/internal/admin/access/invite'){let r=document.querySelector('[data-sai16]');if(r){r.dataset.setupRoute='/internal/admin/owner/setup';r.dataset.loginRoute='/internal/admin/login';r.dataset.controlRoom=room;r.querySelectorAll('a[href="/sigil/internal/admin/control-room"]').forEach(a=>a.href=room);let o=r.querySelector('[data-result-link]');if(o&&o.value&&o.value.includes('/sigil/internal/admin/setup'))o.value=o.value.replace('/sigil/internal/admin/setup','/internal/admin/owner/setup')}}if(p.startsWith('/internal/admin/studio/'))document.querySelectorAll('a[href="/studio"]').forEach(a=>a.href='/internal/admin/studio');if(p==='/internal/admin/payments/historical-backfill')document.querySelectorAll('a[href="/internal/admin/payments/control"]').forEach(a=>a.href='/internal/admin/payments');if(p==='/internal/admin/customer-data')hold('CUSTOMER 360 · HOLD','หน้านี้เก็บไว้เพราะจำเป็น แต่ runtime/backfill actions ยังไม่พร้อมใช้งานจริง — ใช้ Create Job และ Customer Index เป็นทางหลักก่อน');if(p==='/internal/admin/console')hold('LEGACY CONSOLE','ยังคงไว้ชั่วคราวเพราะมี production config อ้างอิงอยู่ กำลังย้าย authority ไป Control Room');if(p==='/internal/admin/sitemap')hold('ROUTE AUDIT · LEGACY VIEW','Internal admin ถูกตัดออกจาก public sitemap โดยตั้งใจ หน้านี้คงไว้ชั่วคราวจน Route Registry แทนที่')}document.addEventListener('click',e=>{if(p!=='/internal/admin/member-intelligence')return;let a=e.target.closest('a[href*="/internal/admin/jobs/create-session"]');if(!a)return;e.preventDefault();location.href=a.href.replace('/internal/admin/jobs/create-session',job)},true);fix();let t;new MutationObserver(()=>{clearTimeout(t);t=setTimeout(fix,30)}).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['href','value']});document.readyState==='loading'?document.addEventListener('DOMContentLoaded',fix,{once:true}):fix()})();